$HistoryLength=0;
$Assumptions=d>1&&-1<c<1;
gate[name_,test_]:=If[TrueQ[test],Print["PASS ",name," ",AbsoluteTime[]],Print["GATE_FAILURE ",name];Quit[1]];
mixedIBP[j_Integer, l_Integer] := Module[{a, b, flux, integrand, phiRule, xRule, rational,
  polynomial, relation, solved, assumptions, polarDomain, algebraicB},
  Print["Deriving angular integration by parts for ", j, ",", l];
  a = d - Cos[theta];
  b = 1 - c Cos[theta] - Sqrt[1 - c^2] Sin[theta] Cos[phi];
  flux = Sin[theta]^(1 - 2 eps) D[a, theta]/(a^j b^l);
  assumptions = d > 1 && -1 < c < 1 && 0 < phi < Pi && eps < -j - l - 2;
  gate["polar integration-by-parts boundary terms vanish", And @@ Table[
    FullSimplify[Limit[flux, theta -> endpoint, Assumptions -> assumptions], assumptions] === 0,
    {endpoint, {0, Pi}}]];
  polarDomain = Reduce[0 < ArcCos[x] < Pi, x, Reals];
  gate["polar coordinate domain evaluated", FreeQ[polarDomain, _Reduce]];
  algebraicB = b /. {theta -> ArcCos[x], Cos[phi] -> yy};
  Print["BEGIN PHI SOLVE ",AbsoluteTime[]]; phiRule = FullSimplify[First[Solve[bb == algebraicB, yy]],
    d > 1 && -1 < c < 1 && polarDomain];
  Print["BEGIN X SOLVE ",AbsoluteTime[]]; xRule = FullSimplify[First[Solve[aa == (a /. theta -> ArcCos[x]), x]]];
  gate["polar coordinate substitutions have no unresolved conditions",
    FreeQ[{phiRule, xRule}, _ConditionalExpression | _Solve]];
  gate["polar coordinate substitutions reconstruct their definitions",
    FullSimplify[(algebraicB /. phiRule) - bb, -1 < c < 1 && polarDomain] === 0 &&
    FullSimplify[((a /. theta -> ArcCos[x]) /. xRule) - aa] === 0];
  integrand = TrigExpand[D[flux, theta]/Sin[theta]^(1 - 2 eps)] /.
    {theta -> ArcCos[x], Cos[phi] -> yy};
  Print["BEGIN RATIONAL ",AbsoluteTime[]]; rational = Factor[FullSimplify[integrand /. phiRule,
    d > 1 && -1 < c < 1 && polarDomain] /. xRule];
  polynomial = Cancel[rational aa^(j + 1) bb^(l + 1)];
  If[!PolynomialQ[polynomial, {aa, bb}], Print["Unreduced polar relation: ", InputForm[polynomial]]];
  gate["polar total derivative reduces to angular monomials", PolynomialQ[polynomial, {aa, bb}]];
  relation = Total[(#[[2]] ml[j + 1 - #[[1, 1]], l + 1 - #[[1, 2]]] &) /@
    CoefficientRules[polynomial, {aa, bb}]];
  gate["integration-by-parts relation reconstructs its defining integrand", Factor[
    (relation /. ml[u_, v_] :> aa^(-u) bb^(-v)) - rational] === 0];
  solved = unknown /. FullSimplify[
    First[Solve[(relation /. ml[j, l + 1] -> unknown) == 0, unknown]], assumptions];
  gate["integration-by-parts solution has no unresolved conditions", FreeQ[solved, _ConditionalExpression | _Solve]];
  gate["integration-by-parts relation isolates the requested master", FreeQ[solved, ml[j, l + 1] | unknown]];
  Print["RECURRENCE ",InputForm[solved]];solved];

Print["BEGIN IBP ",AbsoluteTime[]];
value=MemoryConstrained[TimeConstrained[Block[{$Assumptions=True},mixedIBP[1,1]],110,Print["CHECK_TIMEOUT"];$Failed],512*1024^2,Print["CHECK_MEMORY_LIMIT"];$Failed];
If[value=!=$Failed,Print["CHECK_DONE"]];
Quit[];
